DROP TABLE IF EXISTS `sys_config`;

CREATE TABLE `sys_config`
(
    `ID`        varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
    `TYPE`      varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin  DEFAULT NULL COMMENT '配置类型',
    `NAME`      varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin  DEFAULT NULL COMMENT '配置名',
    `VALUE`     varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '配置值',
    `CHANGE`    varchar(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin   DEFAULT NULL,
    `TENANT_ID` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin  DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`ID`) USING BTREE,
    UNIQUE KEY `TYPE` (`TYPE`,`NAME`,`TENANT_ID`),
    KEY         `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC COMMENT='系统参数配置';


DROP TABLE IF EXISTS `xxl_job_group`;

CREATE TABLE `xxl_job_group`
(
    `id`           int                                                          NOT NULL AUTO_INCREMENT,
    `app_name`     varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '执行器AppName',
    `title`        varchar(12) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '执行器名称',
    `address_type` tinyint                                                      NOT NULL DEFAULT '0' COMMENT '执行器地址类型：0=自动注册、1=手动录入',
    `address_list` text CHARACTER SET utf8mb4 COLLATE utf8mb4_bin COMMENT '执行器地址列表，多地址逗号分隔',
    `update_time`  datetime                                                              DEFAULT NULL,
    `TENANT_ID`    varchar(32)                                                           DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`id`) USING BTREE,
    KEY            `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=21 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

LOCK TABLES `xxl_job_group` WRITE;

