DROP TABLE IF EXISTS `xxl_job_user`;

CREATE TABLE `xxl_job_user`
(
    `id`         int                                                          NOT NULL AUTO_INCREMENT,
    `username`   varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '账号',
    `password`   varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '密码',
    `role`       tinyint                                                      NOT NULL COMMENT '角色：0-普通用户、1-管理员',
    `permission` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT '权限：执行器ID列表，多个逗号分割',
    `TENANT_ID`  varchar(32)                                                   DEFAULT NULL COMMENT '租户ID',
    PRIMARY KEY (`id`) USING BTREE,
    UNIQUE KEY `i_username` (`username`) USING BTREE,
    KEY          `IDX_TENANT_ID` (`TENANT_ID`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

LOCK TABLES `xxl_job_user` WRITE;


UNLOCK TABLES;

DROP TABLE IF EXISTS `xxl_job_lock`;

CREATE TABLE `xxl_job_lock`
(
    `lock_name` varchar(50) NOT NULL COMMENT '锁名称',
    `TENANT_ID` varchar(32) null comment '租户ID',
    PRIMARY KEY (`lock_name`)
) ENGINE=InnoDB
DEFAULT CHARACTER SET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='任务锁表';

LOCK TABLES `xxl_job_lock` WRITE;


UNLOCK TABLES;

DROP TABLE IF EXISTS `cr_data_source`;

create table cr_data_source
(
    ID                 varchar(32)                     not null comment 'id'
        primary key,
    DATA_SOURCE_CODE   varchar(32)                     null comment '数据来源的代码',
    DATA_SOURCE_NAME   varchar(100)                    null comment '数据来源的名称',
    DATA_SOURCE_ORIGIN varchar(1000)                   null comment '数据来源的来源',
    TENANT_ID          varchar(32) collate utf8mb4_bin null comment '租户id'
)
    comment '数据来源表' charset = utf8mb4;








