DROP TABLE IF EXISTS `data_source_category`;

create table data_source_category
(
    ID                        varchar(32)  not null comment '主键'
        primary key,
    DATA_SOURCE_CATEGORY_NAME varchar(100) null comment '数据来源类别名称',
    DATA_SOURCE_CATEGORY_CODE varchar(4)   null comment '数据来源类别代码:D001-供应商;D002-子企业;D003-机构',
    CREATOR                   varchar(100) not null comment '创建人',
    CREATE_DATE               date         not null comment '创建日期时间:yyyy-MM-dd hh24:mm:ss',
    TENANT_ID                 varchar(32)  null comment '租户id'
)
    comment '数据来源类别' collate = utf8mb4_bin;




